// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBlackOpsOne = makeLoadFont('BlackOpsOne');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: blackOpsFamily } = loadBlackOpsOne();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type TankSpeedometerProps = Record<string, any>;

const TankSpeedometer: React.FC<TankSpeedometerProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  topSpeed = 42,
  maxDialSpeed = 50,
  accentColor = "#ff4d00",
  dialColor = "transparent",
}) => {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation: Tank accelerating is heavy, high damping and mass
  const progress = spring({
    fps,
    frame: frame - 15,
    config: { damping: 20, stiffness: 45, mass: 2.5 },
    durationInFrames: Math.min(fps * 3, (durationInSeconds * fps) / 2),
  });

  // Mechanical engine vibration when near or at top speed
  const wobbleIntensity = interpolate(progress, [0.8, 1], [0, 1], { extrapolateRight: "clamp" });
  const wobble = (Math.sin(frame * 0.8) * 0.4 + Math.cos(frame * 1.5) * 0.2) * wobbleIntensity;
  
  const currentSpeed = Math.max(0, (progress * topSpeed) + wobble);
  const currentAngle = -135 + 270 * (currentSpeed / maxDialSpeed);

  // Math for gauge arcs
  const R = 270;
  const C = 2 * Math.PI * R;
  const maxArcLength = C * (270 / 360);
  const currentArcLength = C * ((270 * Math.max(0, currentSpeed) / maxDialSpeed) / 360);
  
  // Redline zone math (from topSpeed up to maxDialSpeed)
  const redlineStartFraction = topSpeed / maxDialSpeed;
  const redlineStartAngleDegrees = 270 * redlineStartFraction;
  const redlineArcLength = C * (270 * (1 - redlineStartFraction) / 360);

  // Generate ticks
  const ticks = [];
  for (let i = 0; i <= maxDialSpeed; i += 1) {
    const isMajor = i % 10 === 0;
    const isMedium = i % 5 === 0 && !isMajor;
    const isMinor = i % 1 === 0 && !isMajor && !isMedium;

    if (isMinor && maxDialSpeed > 80) continue; 

    const angle = -135 + 270 * (i / maxDialSpeed);
    ticks.push({ value: i, angle, isMajor, isMedium, isMinor });
  }

  // Industrial screws for bezel
  const screws = [45, 135, -45, -135].map(angle => (
    <g key={angle} transform={`rotate(${angle}) translate(0, -370)`}>
      <circle r="14" fill="#2a2a2a" stroke="#111" strokeWidth="2" />
      <circle r="8" fill="#1f1f1f" />
      <line x1="-10" y1="0" x2="10" y2="0" stroke="#111" strokeWidth="4" transform={`rotate(${angle * 1.5})`} />
    </g>
  ));

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      {/* Responsive square container */}
      <div style={{ width: height * 0.85, height: height * 0.85, position: "relative" }}>
        <svg 
          width="100%" 
          height="100%" 
          viewBox="-420 -420 840 840" 
          style={{ overflow: "visible", transition: "none" }}
        >
          <defs>
            <filter id="overlay-shadow" x="-30%" y="-30%" width="160%" height="160%">
              <feDropShadow dx="0" dy="25" stdDeviation="20" floodColor="#000" floodOpacity="0.8"/>
            </filter>
            <linearGradient id="metal-grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#3a3a3a" />
              <stop offset="50%" stopColor="#1f1f1f" />
              <stop offset="100%" stopColor="#0a0a0a" />
            </linearGradient>
          </defs>

          {/* Base Gauge Body */}
          <circle r="390" fill="url(#metal-grad)" stroke="#111" strokeWidth="8" filter="url(#overlay-shadow)" />
          <circle r="365" fill={dialColor} stroke="#050505" strokeWidth="12" />
          
          {/* Inner metallic ring */}
          <circle r="350" fill="none" stroke="#2a2c26" strokeWidth="4" />

          {/* Screws */}
          {screws}

          {/* Arcs */}
          {/* Base Track */}
          <circle
            r={R}
            stroke="#222"
            strokeWidth="18"
            fill="none"
            transform="rotate(135)"
            strokeDasharray={`${maxArcLength} ${C}`}
            strokeLinecap="round"
          />
          
          {/* Active Speed Fill Track */}
          <circle
            r={R}
            stroke={accentColor}
            strokeWidth="18"
            fill="none"
            transform="rotate(135)"
            strokeDasharray={`${Math.max(0.01, currentArcLength)} ${C}`}
            strokeLinecap="round"
          />

          {/* Redline Track (Beyond Top Speed) */}
          <circle
            r={R}
            stroke="#ff0000"
            strokeWidth="6"
            fill="none"
            transform="rotate(135)"
            strokeDasharray={`${redlineArcLength} ${C}`}
            strokeDashoffset={-(C * (redlineStartAngleDegrees / 360))}
            opacity="0.6"
          />

          {/* Top Speed Marker */}
          <g transform={`rotate(${ -135 + 270 * (topSpeed / maxDialSpeed) }) translate(0, -325)`}>
            <polygon points="-14,-25 14,-25 0,-4" fill="#ff0000" />
            <text x="0" y="-35" textAnchor="middle" fill="#ff0000" fontSize="16" fontFamily={robotoMonoFamily} fontWeight="bold">
              MAX
            </text>
          </g>

          {/* Ticks and Labels */}
          {ticks.map((tick, idx) => (
            <g key={idx} transform={`rotate(${tick.angle})`}>
              <line
                x1="0"
                y1={tick.isMajor ? -340 : tick.isMedium ? -330 : -325}
                x2="0"
                y2={tick.isMajor ? -300 : tick.isMedium ? -315 : -315}
                stroke={tick.isMajor ? "#ffffff" : tick.isMedium ? "#aaaaaa" : "#555555"}
                strokeWidth={tick.isMajor ? 6 : tick.isMedium ? 4 : 2}
              />
              {tick.isMajor && (
                <g transform={`translate(0, -235) rotate(${-tick.angle})`}>
                  <text
                    x="0"
                    y="0"
                    textAnchor="middle"
                    dominantBaseline="central"
                    fill="#eaeaea"
                    fontSize="42"
                    fontFamily={blackOpsFamily}
                  >
                    {tick.value}
                  </text>
                </g>
              )}
            </g>
          ))}

          {/* Title Text Top Center */}
          <g transform="translate(0, -110)">
            <text x="0" y="0" textAnchor="middle" fill="#555" fontSize="24" fontFamily={robotoMonoFamily} letterSpacing="6" fontWeight="bold">
              TANK
            </text>
            <text x="0" y="30" textAnchor="middle" fill="#888" fontSize="18" fontFamily={robotoMonoFamily} letterSpacing="2">
              DRIVE SYSTEM
            </text>
          </g>

          {/* Digital Readout Screen */}
          <g transform="translate(0, 110)">
            <rect x="-100" y="-55" width="200" height="110" rx="12" fill="#050505" stroke="#222" strokeWidth="6" />
            
            {/* Inner screen shadow */}
            <rect x="-97" y="-52" width="194" height="104" rx="10" fill="transparent" stroke="#000" strokeWidth="4" />
            
            <text 
              x="0" 
              y="15" 
              textAnchor="middle" 
              dominantBaseline="middle" 
              fill={accentColor} 
              fontSize="72" 
              fontFamily={robotoMonoFamily} 
              fontWeight="bold" 
              style={{ textShadow: `0 0 15px ${accentColor}88` }}
            >
              {Math.max(0, currentSpeed).toFixed(0).padStart(2, '0')}
            </text>
            
            <text x="0" y="75" textAnchor="middle" fill="#666" fontSize="22" fontFamily={robotoMonoFamily} letterSpacing="4" fontWeight="bold">
              MPH
            </text>
          </g>

          {/* Needle Base / Pivot Shadow */}
          <circle r="50" fill="rgba(0,0,0,0.6)" transform="translate(0, 15)" />

          {/* Animating Needle */}
          <g transform={`rotate(${currentAngle})`}>
            {/* Needle drop shadow */}
            <polygon points="-16,0 0,-340 16,0 0,60" fill="rgba(0,0,0,0.4)" transform="translate(-10, 15)" />
            
            {/* Main Needle Blade */}
            <polygon points="-14,0 0,-345 14,0 0,60" fill={accentColor} />
            
            {/* Needle center line detail */}
            <line x1="0" y1="-330" x2="0" y2="40" stroke="#000000" strokeWidth="2" opacity="0.4" />
            
            {/* Heavy Pivot Caps */}
            <circle r="45" fill="#1a1a1a" stroke="#333" strokeWidth="6" />
            <circle r="25" fill="#111" />
            <circle r="10" fill={accentColor} />
          </g>
          
          {/* Glass reflection highlight */}
          <path 
            d="M -300 -150 A 340 340 0 0 1 300 -150 A 400 400 0 0 0 -300 -150 Z" 
            fill="rgba(255, 255, 255, 0.03)" 
            style={{ pointerEvents: "none" }}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default TankSpeedometer;